const PYTHON_INT_LITERAL = /^[+-]?[0-9]+(?:_[0-9]+)*$/;
const NEGATIVE_NUMBER_TOKEN = /^-[0-9]+(?:_[0-9]+)*$/;

export function parsePythonIntLiteral(rawValue, optionName, progName) {
  const value = String(rawValue);

  if (!PYTHON_INT_LITERAL.test(value)) {
    throw createArgumentError(progName, `argument ${optionName}: invalid int value: '${value}'`);
  }

  return BigInt(value.replaceAll('_', ''));
}

