import { createArgumentError, createHelpExit } from './errors.mjs';
import { parsePythonIntLiteral, isNegativeNumberLikeToken } from './int-literal.mjs';
import { getProgramName } from './program-name.mjs';

function canConsumeAsValue(token) {
  if (token === undefined) {
    return false;
  }

  if (!token.startsWith('-') || token === '-') {
    return true;
  }

  return isNegativeNumberLikeToken(token);
}

function assignOptionValue(values, optionName, rawValue, progName) {
  if (optionName === '--a') {
    values.a = parsePythonIntLiteral(rawValue, optionName, progName);
    return;
  }

  if (optionName === '--b') {
    values.b = parsePythonIntLiteral(rawValue, optionName, progName);
    return;
  }

  values.c = rawValue;
}

function expectedOneArgument(optionName, progName) {
  throw createArgumentError(progName, `argument ${optionName}: expected one argument`);
}

function ignoredHelpArgument(progName, rawValue) {
  throw createArgumentError(progName, `argument -h/--help: ignored explicit argument '${rawValue}'`);
}

export function parseTest14Args(argv = process.argv.slice(2), progName = getProgramName()) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '--help' || token === '-h' || (token.startsWith('-h') && !token.startsWith('-h='))) {
      throw createHelpExit(progName);
    }

    if (token.startsWith('--help=')) {
      ignoredHelpArgument(progName, token.slice('--help='.length));
    }

    if (token.startsWith('-h=')) {
      ignoredHelpArgument(progName, token.slice('-h='.length));
    }

    if (token === '--a' || token === '--b' || token === '--c') {
      const nextToken = argv[index + 1];

      if (!canConsumeAsValue(nextToken)) {
        expectedOneArgument(token, progName);
      }

      assignOptionValue(values, token, nextToken, progName);
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      assignOptionValue(values, '--a', token.slice('--a='.length), progName);
      continue;
    }

    if (token.startsWith('--b=')) {
      assignOptionValue(values, '--b', token.slice('--b='.length), progName);
      continue;
    }

    if (token.startsWith('--c=')) {
      assignOptionValue(values, '--c', token.slice('--c='.length), progName);
      continue;
    }

    extras.push(token);
  }

  const missingOptions = [];

  if (values.a === undefined) {
    missingOptions.push('--a');
  }

  if (values.b === undefined) {
    missingOptions.push('--b');
  }

  if (values.c === undefined) {
    missingOptions.push('--c');
  }

  if (missingOptions.length > 0) {
    throw createArgumentError(
      progName,
      `the following arguments are required: ${missingOptions.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    throw createArgumentError(progName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

