import {
  BASE58_ALPHABET,
  BASE58_BASE,
  BASE58_ZERO_CHARACTER,
} from './alphabet.mjs';
import { pythonDivmod } from './math.mjs';

export function b58encodeInt(value, defaultOne = true) {
  if (value === 0n) {
    return defaultOne ? BASE58_ZERO_CHARACTER : '';
  }

  let remaining = typeof value === 'bigint' ? value : BigInt(value);
  let encoded = '';

  while (remaining !== 0n) {
    const { quotient, remainder } = pythonDivmod(remaining, BASE58_BASE);
    encoded = BASE58_ALPHABET[Number(remainder)] + encoded;
    remaining = quotient;
  }

  return encoded;
}

